import React, { useState, useEffect } from 'react';
import { FaSort, FaFilter, FaEye, FaEdit, FaTrash, FaPlus, FaSearch } from 'react-icons/fa';

function ChambrePage() {
  // Données simulées pour les chambres
  const mockChambres = [
    { n_chambre: "A101", capacite_max: 2, etat_chambre: "Disponible", n_bat: 1 },
    { n_chambre: "A102", capacite_max: 1, etat_chambre: "Occupée", n_bat: 1 },
    { n_chambre: "A103", capacite_max: 2, etat_chambre: "En rénovation", n_bat: 1 },
    { n_chambre: "B201", capacite_max: 3, etat_chambre: "Disponible", n_bat: 2 },
    { n_chambre: "B202", capacite_max: 1, etat_chambre: "Occupée", n_bat: 2 },
    { n_chambre: "C301", capacite_max: 2, etat_chambre: "Hors service", n_bat: 3 },
    { n_chambre: "C302", capacite_max: 2, etat_chambre: "Disponible", n_bat: 3 },
    { n_chambre: "D101", capacite_max: 4, etat_chambre: "Occupée", n_bat: 4 },
    { n_chambre: "D102", capacite_max: 1, etat_chambre: "Disponible", n_bat: 4 },
    { n_chambre: "E201", capacite_max: 2, etat_chambre: "En rénovation", n_bat: 5 },
  ];

  // Données simulées pour les bâtiments
  const mockBatiments = [
    { n_bat: 1, nom_bat: "Résidence Alpha" },
    { n_bat: 2, nom_bat: "Résidence Beta" },
    { n_bat: 3, nom_bat: "Résidence Gamma" },
    { n_bat: 4, nom_bat: "Résidence Delta" },
    { n_bat: 5, nom_bat: "Résidence Epsilon" },
  ];
  
  const etatsChambres = ["Disponible", "Occupée", "En rénovation", "Hors service"];
  const [chambres, setChambres] = useState([]);
  const [batiments, setBatiments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedChambre, setSelectedChambre] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [showFormModal, setShowFormModal] = useState(false);
  const [formMode, setFormMode] = useState('add'); // 'add' ou 'edit'
  const [formData, setFormData] = useState({
    n_chambre: '',
    capacite_max: 1,
    etat_chambre: 'Disponible',
    n_bat: ''
  });
  const [filterCriteria, setFilterCriteria] = useState({
    n_bat: '',
    etat_chambre: ''
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [searchCapacite, setSearchCapacite] = useState('');
  const [showAdvancedSearch, setShowAdvancedSearch] = useState(false);

  useEffect(() => {
    // Simuler un délai de chargement pour imiter une requête API
    const timer = setTimeout(() => {
      setChambres(mockChambres);
      setBatiments(mockBatiments);
      setLoading(false);
    }, 800);

    return () => clearTimeout(timer);
  }, []);

  const handleView = (chambre) => {
    setSelectedChambre(chambre);
    setShowModal(true);
  };

  const handleAdd = () => {
    setFormData({
      n_chambre: '',
      capacite_max: 1,
      etat_chambre: 'Disponible',
      n_bat: ''
    });
    setFormMode('add');
    setShowFormModal(true);
  };

  const handleEdit = (chambre) => {
    setFormData({
      n_chambre: chambre.n_chambre,
      capacite_max: chambre.capacite_max,
      etat_chambre: chambre.etat_chambre,
      n_bat: chambre.n_bat
    });
    setFormMode('edit');
    setShowFormModal(true);
  };

  const handleDelete = async (n_chambre) => {
    if (window.confirm('Êtes-vous sûr de vouloir supprimer cette chambre?')) {
      try {
        // Simulation de suppression
        setChambres(chambres.filter(chambre => chambre.n_chambre !== n_chambre));
      } catch (err) {
        setError('Erreur lors de la suppression');
        console.error('Erreur:', err);
      }
    }
  };

  const handleFormChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: name === 'capacite_max' ? parseInt(value, 10) : value
    });
  };

  const handleFormSubmit = async (e) => {
    e.preventDefault();
    try {
      if (formMode === 'add') {
        // Simulation d'ajout
        setChambres([...chambres, formData]);
      } else {
        // Simulation de mise à jour
        setChambres(
          chambres.map(chambre => 
            chambre.n_chambre === formData.n_chambre ? formData : chambre
          )
        );
      }
      setShowFormModal(false);
    } catch (err) {
      setError(`Erreur lors de l'${formMode === 'add' ? 'ajout' : 'édition'}`);
      console.error('Erreur:', err);
    }
  };

  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
  };
  
  const handleCapaciteChange = (e) => {
    setSearchCapacite(e.target.value);
  };
  
  const toggleAdvancedSearch = () => {
    setShowAdvancedSearch(!showAdvancedSearch);
  };
  
  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilterCriteria({
      ...filterCriteria,
      [name]: value
    });
  };

  const filteredChambres = chambres.filter(chambre => {
    // Filtrage par critères de base (bâtiment et état)
    const matchesBasicFilters = (
      (filterCriteria.n_bat === '' || chambre.n_bat.toString() === filterCriteria.n_bat) &&
      (filterCriteria.etat_chambre === '' || chambre.etat_chambre === filterCriteria.etat_chambre)
    );
  
    // Recherche par numéro de chambre
    const matchesSearch = searchTerm === '' || 
      chambre.n_chambre.toLowerCase().includes(searchTerm.toLowerCase());
    
    // Recherche par capacité
    const matchesCapacite = searchCapacite === '' || 
      chambre.capacite_max === parseInt(searchCapacite, 10);
  
    return matchesBasicFilters && matchesSearch && matchesCapacite;
  });
  

  const sortChambres = (field) => {
    const sortedChambres = [...chambres].sort((a, b) => {
      if (a[field] < b[field]) return -1;
      if (a[field] > b[field]) return 1;
      return 0;
    });
    setChambres(sortedChambres);
  };

  // Extraire les valeurs uniques pour les filtres
  const capacites = [...new Set(chambres.map(c => c.capacite_max))].sort((a, b) => a - b);

  // Fonction pour obtenir le nom du bâtiment à partir de son ID
  const getBatimentName = (n_bat) => {
    const batiment = batiments.find(b => b.n_bat === n_bat);
    return batiment ? batiment.nom_bat : `Bâtiment ${n_bat}`;
  };

  return (
    <div className="p-4">
      <h1 className="text-2xl font-bold text-blue-500 mb-6">Gestion des Chambres</h1>
      {/* Recherche */}
      <div className="bg-white p-4 rounded-lg shadow mb-4">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between">
          <div className="flex-1 mb-2 md:mb-0 md:mr-4">
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <FaSearch className="text-gray-400" />
              </div>
              <input
                type="text"
                placeholder="Rechercher par numéro de chambre..."
                value={searchTerm}
                onChange={handleSearchChange}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
          </div>
          <button
            onClick={toggleAdvancedSearch}
            className="text-blue-500 hover:text-blue-700 flex items-center"
          >
            {showAdvancedSearch ? 'Masquer' : 'Afficher'} la recherche avancée
          </button>
        </div>

        {showAdvancedSearch && (
          <div className="mt-4 pt-4 border-t border-gray-200">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Capacité exacte
                </label>
                <select
                  value={searchCapacite}
                  onChange={handleCapaciteChange}
                  className="w-full p-2 border border-gray-300 rounded-md"
                >
                  <option value="">Toutes les capacités</option>
                  {capacites.map((cap) => (
                    <option key={cap} value={cap}>{cap} personne(s)</option>
                  ))}
                </select>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Filtres */}
      <div className="bg-white p-4 rounded-lg shadow mb-6">
        <h2 className="text-lg font-semibold mb-3 flex items-center">
          <FaFilter className="mr-2" /> Filtres
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Bâtiment</label>
            <select
              name="n_bat"
              value={filterCriteria.n_bat}
              onChange={handleFilterChange}
              className="w-full p-2 border border-gray-300 rounded-md"
            >
              <option value="">Tous les bâtiments</option>
              {batiments.map((bat) => (
                <option key={bat.n_bat} value={bat.n_bat.toString()}>{bat.nom_bat || `Bâtiment ${bat.n_bat}`}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">État</label>
            <select
              name="etat_chambre"
              value={filterCriteria.etat_chambre}
              onChange={handleFilterChange}
              className="w-full p-2 border border-gray-300 rounded-md"
            >
              <option value="">Tous les états</option>
              {etatsChambres.map((etat, index) => (
                <option key={index} value={etat}>{etat}</option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* Bouton d'ajout */}
      <div className="mb-4">
        <button 
          className="bg-green-500 hover:bg-green-600 text-white py-2 px-4 rounded-md transition duration-300 flex items-center"
          onClick={handleAdd}
        >
          <FaPlus className="mr-2" /> Ajouter une chambre
        </button>
      </div>

      {/* Résultats de recherche */}
      <div className="mb-4">
        <p className="text-gray-600">
          {filteredChambres.length} chambre(s) trouvée(s)
        </p>
      </div>


      {/* Tableau des chambres */}
      {loading ? (
        <div className="text-center py-10">
          <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500 mx-auto"></div>
          <p className="mt-2 text-gray-600">Chargement des données...</p>
        </div>
      ) : error ? (
        <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative" role="alert">
          <strong className="font-bold">Erreur!</strong>
          <span className="block sm:inline"> {error}</span>
        </div>
      ) : (
        <div className="overflow-x-auto bg-white rounded-lg shadow">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  <button onClick={() => sortChambres('n_chambre')} className="flex items-center">
                    Numéro <FaSort className="ml-1" />
                  </button>
                </th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  <button onClick={() => sortChambres('n_bat')} className="flex items-center">
                    Bâtiment <FaSort className="ml-1" />
                  </button>
                </th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  <button onClick={() => sortChambres('capacite_max')} className="flex items-center">
                    Capacité <FaSort className="ml-1" />
                  </button>
                </th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  <button onClick={() => sortChambres('etat_chambre')} className="flex items-center">
                    État <FaSort className="ml-1" />
                  </button>
                </th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Actions
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {filteredChambres.length === 0 ? (
                <tr>
                  <td colSpan="5" className="px-6 py-4 text-center text-sm text-gray-500">
                    Aucune chambre trouvée
                  </td>
                </tr>
              ) : (
                filteredChambres.map((chambre) => (
                  <tr key={chambre.n_chambre} className="hover:bg-gray-50">
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{chambre.n_chambre}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{getBatimentName(chambre.n_bat)}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{chambre.capacite_max} personne(s)</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full 
                        ${chambre.etat_chambre === 'Occupée' ? 'bg-red-100 text-red-800' : 
                          chambre.etat_chambre === 'Disponible' ? 'bg-green-100 text-green-800' : 
                          chambre.etat_chambre === 'En rénovation' ? 'bg-yellow-100 text-yellow-800' :
                          'bg-gray-100 text-gray-800'}`}>
                        {chambre.etat_chambre}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                      <button 
                        onClick={() => handleView(chambre)} 
                        className="text-blue-600 hover:text-blue-900 mr-3"
                        title="Voir les détails"
                      >
                        <FaEye />
                      </button>
                      <button 
                        onClick={() => handleEdit(chambre)} 
                        className="text-yellow-600 hover:text-yellow-900 mr-3"
                        title="Modifier"
                      >
                        <FaEdit />
                      </button>
                      <button 
                        onClick={() => handleDelete(chambre.n_chambre)} 
                        className="text-red-600 hover:text-red-900"
                        title="Supprimer"
                      >
                        <FaTrash />
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal de détails */}
      {showModal && selectedChambre && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-lg shadow-lg w-full max-w-md">
            <h2 className="text-xl font-bold mb-4">Détails de la chambre {selectedChambre.n_chambre}</h2>
            <div className="mb-4">
              <p><strong>Bâtiment:</strong> {getBatimentName(selectedChambre.n_bat)}</p>
              <p><strong>Capacité maximale:</strong> {selectedChambre.capacite_max} personne(s)</p>
              <p><strong>État:</strong> {selectedChambre.etat_chambre}</p>
            </div>
            <div className="flex justify-end">
              <button 
                onClick={() => setShowModal(false)}
                className="bg-gray-300 hover:bg-gray-400 text-gray-800 font-bold py-2 px-4 rounded"
              >
                Fermer
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal de formulaire (ajout/édition) */}
      {showFormModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-lg shadow-lg w-full max-w-md">
            <h2 className="text-xl font-bold mb-4">
              {formMode === 'add' ? 'Ajouter une chambre' : 'Modifier la chambre'}
            </h2>
            <form onSubmit={handleFormSubmit}>
              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Numéro de chambre
                </label>
                <input
                  type="text"
                  name="n_chambre"
                  value={formData.n_chambre}
                  onChange={handleFormChange}
                  disabled={formMode === 'edit'}
                  className="w-full p-2 border border-gray-300 rounded-md"
                  required
                />
              </div>
              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Bâtiment
                </label>
                <select
                  name="n_bat"
                  value={formData.n_bat}
                  onChange={handleFormChange}
                  className="w-full p-2 border border-gray-300 rounded-md"
                  required
                >
                  <option value="">Sélectionnez un bâtiment</option>
                  {batiments.map((bat) => (
                    <option key={bat.n_bat} value={bat.n_bat}>
                      {bat.nom_bat || `Bâtiment ${bat.n_bat}`}
                    </option>
                  ))}
                </select>
              </div>
              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Capacité maximale
                </label>
                <input
                  type="number"
                  name="capacite_max"
                  value={formData.capacite_max}
                  onChange={handleFormChange}
                  min="1"
                  className="w-full p-2 border border-gray-300 rounded-md"
                  required
                />
              </div>
              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  État de la chambre
                </label>
                <select
                  name="etat_chambre"
                  value={formData.etat_chambre}
                  onChange={handleFormChange}
                  className="w-full p-2 border border-gray-300 rounded-md"
                  required
                >
                  <option value="Disponible">Disponible</option>
                  <option value="Occupée">Occupée</option>
                  <option value="En rénovation">En rénovation</option>
                  <option value="Hors service">Hors service</option>
                </select>
              </div>
              <div className="flex justify-end space-x-2">
                <button
                  type="button"
                  onClick={() => setShowFormModal(false)}
                  className="bg-gray-300 hover:bg-gray-400 text-gray-800 font-bold py-2 px-4 rounded"
                >
                  Annuler
                </button>
                <button
                  type="submit"
                  className="bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded"
                >
                  {formMode === 'add' ? 'Ajouter' : 'Enregistrer'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default ChambrePage;
